from collections import deque

class Solution:
    def kSimilarity(self, s1: str, s2: str) -> int:
        start, target = ''.join(s1), ''.join(s2)
        q = deque([(start, 0)])
        seen = {start}
        while q:
            cur, d = q.popleft()
            if cur == target:
                return d
            for i in range(len(cur)):
                for j in range(i + 1, len(cur)):
                    if cur[i] != cur[j]:
                        nxt = list(cur)
                        nxt[i], nxt[j] = nxt[j], nxt[i]
                        nxt = ''.join(nxt)
                        if nxt not in seen:
                            seen.add(nxt)
                            q.append((nxt, d + 1))
        return -1

