#include <string>
#include <queue>
#include <unordered_set>
using namespace std;

class Solution {
public:
    int kSimilarity(string s1, string s2) {
        queue<pair<string,int>> q;
        unordered_set<string> seen;
        q.push({s1, 0});
        seen.insert(s1);
        while (!q.empty()) {
            auto [cur, d] = q.front(); q.pop();
            if (cur == s2) return d;
            int n = cur.size();
            for (int i = 0; i < n; i++)
                for (int j = i + 1; j < n; j++) {
                    if (cur[i] != cur[j]) {
                        string nxt = cur;
                        swap(nxt[i], nxt[j]);
                        if (!seen.count(nxt)) {
                            seen.insert(nxt);
                            q.push({nxt, d + 1});
                        }
                    }
                }
        }
        return -1;
    }
};

