import java.util.*;

class Solution {
    public int kSimilarity(String s1, String s2) {
        Deque<Object[]> q = new ArrayDeque<>();
        Set<String> seen = new HashSet<>();
        q.offer(new Object[]{s1, 0});
        seen.add(s1);
        while (!q.isEmpty()) {
            Object[] top = q.poll();
            String cur = (String) top[0];
            int d = (Integer) top[1];
            if (cur.equals(s2)) return d;
            char[] arr = cur.toCharArray();
            for (int i = 0; i < arr.length; i++)
                for (int j = i + 1; j < arr.length; j++) {
                    if (arr[i] != arr[j]) {
                        char[] nxt = arr.clone();
                        char t = nxt[i]; nxt[i] = nxt[j]; nxt[j] = t;
                        String ns = new String(nxt);
                        if (seen.add(ns)) q.offer(new Object[]{ns, d + 1});
                    }
                }
        }
        return -1;
    }
}

